insert into public.development_stages (content_id, version, stage_key, name, position, approximate_band, focus_areas, description, next_stage_preview, entry_guidance, review_status, effective_from)
values
  ('stage.preparing', 1, 'preparing', 'Preparing for arrival', 1, 'homecoming date in the future', array['Home setup and safety','Supplies','Routine agreement','Choosing a veterinarian','First-night plan'], 'Getting your home and routine ready counts as head start parenting. Everything you sort out now is one less thing to juggle when {name} arrives.', 'Once {name} is home, the first couple of weeks are all about settling in - sleep, routine, and gentle bonding.', '{"kind":"homecoming_future"}', 'pending_professional_review', '2026-07-26'),
  ('stage.settling_in', 1, 'settling_in', 'Settling in', 2, 'first ~2 weeks home', array['Predictable routine','Sleep and crate comfort','Gentle bonding','Name response','Potty rhythm','Low-pressure home exploration'], '{name} is learning that your home is safe and predictable. Routine matters more than training right now - though tiny, fun sessions are a lovely way to bond.', 'Many puppies are ready for a bit more structure after a week or two - short training moments and gentle new experiences.', '{"approx_home_age":"first_2_weeks"}', 'pending_professional_review', '2026-07-26'),
  ('stage.foundations', 1, 'foundations', 'Foundations', 3, '~8-12 weeks', array['Marker and name basics','Short fun training','Handling comfort','Positive early socialization within veterinary guidance','Alone-time foundations'], 'Short, playful practice builds the basics: {name}''s name, a marker word, being handled, and feeling fine alone for a moment. Keep everything easy and rewarding.', 'Around three to four months, many puppies are ready to widen their world - more places, surfaces, and friendly encounters.', '{"age_min_weeks":8,"age_max_weeks":12}', 'pending_professional_review', '2026-07-26'),
  ('stage.exploration', 1, 'exploration', 'Exploration and socialization', 4, '~12-16 weeks', array['Broadening positive exposure','Recall foundations','Leash introduction','Handling and grooming comfort'], 'This is a wonderful window for positive new experiences. One calm, pleasant encounter beats ten rushed ones.', 'Teething often arrives around four months - expect more chewing and plan for it rather than fighting it.', '{"age_min_weeks":12,"age_max_weeks":16}', 'pending_professional_review', '2026-07-26'),
  ('stage.teething', 1, 'teething', 'Teething', 5, '~16-24 weeks', array['Appropriate chew management','Patience with mouthing','Maintaining training momentum','Calm-settle practice'], 'Sore gums mean chewing is a need, not naughtiness. Offer good options, keep sessions short, and keep routines steady.', 'As adolescence approaches, {name} may test boundaries they knew perfectly well. That is normal - consistency wins.', '{"age_min_weeks":16,"age_max_weeks":24}', 'pending_professional_review', '2026-07-26'),
  ('stage.early_adolescence', 1, 'early_adolescence', 'Early adolescence', 6, '~6-9 months', array['Reinforcing recall and leash skills','Impulse-control games','Sustaining socialization quality'], '{name} is getting braver and more independent. Keep recall rewarding, keep practicing in new places, and do not take regressions personally.', 'Full adolescence can bring bigger energy and selective hearing. The habits you keep now carry you through it.', '{"age_min_months":6,"age_max_months":9}', 'pending_professional_review', '2026-07-26'),
  ('stage.adolescence', 1, 'adolescence', 'Adolescence', 7, '~9-18 months', array['Consistency through regression phases','Generalizing skills to new places','Exercise balance'], 'The teenage phase: enthusiasm, energy, and the occasional "who, me?". Stay consistent, keep it rewarding, and this passes.', 'Most dogs settle into adulthood between one and two years - the rhythm you have built becomes your life together.', '{"age_min_months":9,"age_max_months":18}', 'pending_professional_review', '2026-07-26'),
  ('stage.adulthood', 1, 'adulthood', 'Adulthood', 8, '~18 months +', array['Maintenance practice','Enrichment variety','Routine care rhythm'], 'The foundations are laid. Now it is maintenance, enrichment, and enjoying the dog you have raised together.', null, '{"age_min_months":18}', 'pending_professional_review', '2026-07-26');
