insert into public.training_skills (content_id, version, skill_group, title, promise, steps, prerequisite_skill_refs, stage_guidance, effort_band, recommended_frequency, common_mistakes, watch_for, going_well, review_status, effective_from)
values
  ('skill.marker_intro', 1, 'Foundations', 'Marker word ("yes!")', 'One little word that tells {name} exactly which moment earned the treat.', '["Pick one short word the whole household will use - yes! works.","Say it once, then hand {name} a treat. Word first, treat after.","Repeat 5-8 times. That is the whole session.","Over the next days, say it the instant {name} does something you like, then treat."]', '{}', 'settling_in', 'tiny', '3-5/week', array['Marking late','Treating before marking'], 'Marking late (the word should catch the exact moment) - reaching for the treat before you have said the word.', '{name}''s ears perk when they hear it - the word now means "that! do that again."', 'pending_professional_review', '2026-07-26'),
  ('skill.name_response', 1, 'Foundations', 'Name response', '{name} hears their name and thinks "something good is about to happen."', '["Wait until {name} is not looking at you.","Say their name once, brightly.","The instant they turn toward you, mark and treat.","If they do not turn, do not repeat the name - make a small fun noise instead, and make it easier next time.","Practice in different rooms, then with mild distractions."]', '{}', 'settling_in', 'tiny', '4-6/week', array['Repeating the name','Using it for scolding'], 'Repeating the name ("Maple. Maple! MAPLE.") teaches that the first call does not count - never use the name for scolding.', 'A quick head-turn on the first call, most of the time, in easy places.', 'pending_professional_review', '2026-07-26'),
  ('skill.sit', 1, 'Foundations', 'Sit', 'A polite default that beats jumping every time.', '["Hold a treat at {name}''s nose, then move it slowly up and slightly back.","As the head comes up, the bottom goes down. The moment it touches - mark and treat.","After a few successes, try the same hand motion without a treat in the hand; treat from the other hand.","Add the word sit just before the motion once the movement is reliable."]', array['skill.marker_intro'], 'foundations', 'tiny', '3-5/week', array['Luring forever','Pushing the rear down'], 'Luring forever (fade the treat from the guiding hand early) - never push the rear down, let {name} figure it out.', '{name} sits on the word or a small hand signal, no treat in sight until after.', 'pending_professional_review', '2026-07-26'),
  ('skill.hand_target', 1, 'Foundations', 'Hand target ("touch")', 'A friendly "come here and check in" that works anywhere.', '["Present a flat palm a hand-width from {name}''s nose.","Puppies are curious - when the nose boops the palm, mark and treat.","Move the palm to new spots: lower, higher, left, right.","Add the word touch just before presenting the hand."]', array['skill.marker_intro'], 'foundations', 'tiny', '3-4/week', array['Moving the hand toward the puppy'], 'Moving your hand toward {name} (let them come to the hand) - sessions longer than a minute or two.', '{name} crosses the room to boop your palm.', 'pending_professional_review', '2026-07-26'),
  ('skill.recall_foundations', 1, 'Recall and safety', 'Recall ("come")', 'The one that matters most: {name} comes when called, happily.', '["Start two steps away in a quiet room. Say {name}, come! once, warmly.","The instant they move toward you, celebrate - mark, treat generously, make it a party.","Release them to go back to whatever they were doing. Coming to you should not end the fun.","Gradually add distance, then new rooms, then the garden.","Sometimes grab the collar gently before treating - so a reach is not scary later."]', array['skill.name_response'], 'foundations', 'short', '3-5/week', array['Calling for unpleasant things','Repeating the cue','Practicing only indoors forever'], 'Calling {name} for things they dislike (baths, ending play) - go and get them instead - repeating the cue - staying at one difficulty forever, or jumping to the park too soon.', 'A fast, happy turn-and-run to you in easy places, every time.', 'pending_professional_review', '2026-07-26'),
  ('skill.leave_it', 1, 'House manners', 'Leave it', '{name} chooses to look away from tempting things - because it pays better.', '["Close a boring treat in your fist and let {name} investigate.","Wait out the licking and pawing. The instant they pull away - mark and treat from the other hand.","Repeat until they pull back from the fist immediately.","Move the closed hand to the floor; same game.","Add the words leave it just before presenting, once the pull-away is quick."]', array['skill.marker_intro'], 'exploration', 'short', '2-4/week', array['Snatching the item away','Escalating too fast'], 'Escalating too fast - an open hand or dropped food is graduate-level. Do not snatch the item away; the point is {name} choosing.', '{name} sees the fist, looks at you instead.', 'pending_professional_review', '2026-07-26'),
  ('skill.drop_it', 1, 'House manners', 'Drop it (trade)', '{name} gives things up willingly, because trading always pays.', '["While {name} holds a toy, offer a treat near their nose.","When the toy drops - mark, treat, and give the toy right back when it is safe to.","Add the words drop it just before the offer.","Practice with different toys; keep the trade generous."]', '{}', 'exploration', 'short', '2-3/week', array['Chasing the puppy','Trading down'], 'Chasing {name} to get the item (that is the best game ever - do not start it) - always trading down (losing the toy forever teaches {name} to guard it).', 'The toy drops on the words, tail still wagging.', 'pending_professional_review', '2026-07-26'),
  ('skill.crate_comfort', 1, 'Calm behavior', 'Crate comfort', 'The crate becomes {name}''s own calm room, not a cage.', '["Set the crate up cozy, door open. Drop treats inside and walk away - no pressure.","Feed meals just inside the door, then further in.","When {name} settles inside on their own, calmly drop a treat in.","Close the door for a few seconds while treating, open before any fuss.","Build duration in small steps, always ending while it is easy."]', '{}', 'settling_in', 'short', 'daily at first', array['Using the crate as punishment','Rushing duration'], 'Using the crate for time-outs - rushing duration (one bad scare undoes a week of good work).', '{name} wanders in for naps with the door open.', 'pending_professional_review', '2026-07-26'),
  ('skill.settle_on_mat', 1, 'Calm behavior', 'Settle on a mat', 'An off-switch: {name} learns that the mat means relax.', '["Put a mat down; treat {name} for any interest in it.","Treat for paws on, then for sitting, then for lying down - at {name}''s pace.","Feed calm: slow, quiet treats between the paws while they are lying down.","Take a step away and return before {name} gets up. Build slowly.","Practice while you sit nearby with a cup of tea - boring is the point."]', array['skill.marker_intro'], 'foundations', 'short', '3-4/week', array['Only practicing when already tired','Expecting long holds early'], 'Only practicing when {name} is already sleepy (fine to start, but practice mildly awake too) - expecting long holds in week one.', '{name} sees the mat come out and flops onto it.', 'pending_professional_review', '2026-07-26'),
  ('skill.alone_time', 1, 'Calm behavior', 'Alone-time foundations', '{name} learns that being alone is safe and short-lived - the foundation against separation stress.', '["Start with {name} settled (mat or crate). Step out of sight for two seconds, return calmly.","Return before any fussing - you are teaching that you always come back and it is fine.","Vary it: sometimes two seconds, sometimes ten. Keep returns boring.","Build toward leaving the room during normal life - kettle on, coat on and off again.","Work up to real short absences only when {name} is relaxed at every step."]', array['skill.crate_comfort'], 'settling_in', 'short', '3-5/week', array['Sneaking out','Jumping to long absences'], 'Sneaking out (let departures be visible and unremarkable) - jumping from one minute to one hour.', '{name} glances up when you leave the room, then goes back to their chew.', 'pending_professional_review', '2026-07-26'),
  ('skill.paw_handling', 1, 'Handling and grooming prep', 'Paw handling', 'Nail trims and muddy-paw wipes without a wrestling match.', '["Touch a paw for one second, mark, treat. That is it.","Progress to holding briefly, then to gently pressing a toe.","Pair every touch with something good; stop before {name} pulls away.","Later, touch paws with a towel, then show the nail clippers nearby - no clipping yet, just good associations."]', '{}', 'settling_in', 'tiny', '3-4/week', array['Gripping tightly','Continuing past discomfort'], 'Gripping tightly when {name} pulls back (release on calm, not on struggle - better yet, go slower) - pushing past discomfort.', '{name} offers a paw and leaves it in your hand.', 'pending_professional_review', '2026-07-26'),
  ('skill.body_handling', 1, 'Handling and grooming prep', 'Ears, mouth, body handling', 'Vet visits and grooming feel like old news, because gentle hands are normal.', '["In a calm moment, touch an ear for a second - mark, treat.","Rotate areas over sessions: ears, lips (lift briefly), collar area, tail, belly.","Keep sessions under two minutes, always ending on an easy touch.","Add gentle restraint last: a soft hold for one second, treat, release."]', array['skill.paw_handling'], 'foundations', 'tiny', '2-4/week', array['Long sessions','Skipping the pairing with rewards'], 'Long sessions - handling without pairing rewards (touch should predict good things, not just happen).', '{name} leans in for the exam-style once-over.', 'pending_professional_review', '2026-07-26'),
  ('skill.harness_intro', 1, 'Leash skills', 'Collar/harness introduction', 'The harness predicts adventures, not restraint.', '["Show the harness; treat {name} for sniffing it.","Feed treats through the head opening so {name} pokes their own head in.","Clip it on loosely for a few seconds while treating, then off.","Build up wearing time during pleasant things - meals, play."]', '{}', 'settling_in', 'tiny', '2-3/week', array['Forcing it on','Leaving it on while distressed'], 'Forcing it over the head - leaving it on while {name} is distressed - take a step back instead.', '{name} sees the harness and comes over.', 'pending_professional_review', '2026-07-26'),
  ('skill.loose_leash', 1, 'Leash skills', 'Loose-leash foundations', 'Walks where the leash stays soft - starting in the hallway, not the high street.', '["Indoors, clip the leash on and just walk around treating {name} for being near your leg.","When the leash goes tight, stop being interesting: stand still. The moment it slackens, mark, treat, walk on.","Change direction often - following you becomes the game.","Take it to the garden, then quiet outdoor spots, keeping sessions short."]', array['skill.harness_intro'], 'exploration', 'short', '3-4/week', array['Letting pulling pay off sometimes','Sessions too long'], 'Letting pulling work sometimes (if tight leash ever gets {name} where they want, pulling pays) - sessions long enough to get frustrating for either of you.', 'Slack-leash steps beside you in easyish places, {name} checking in.', 'pending_professional_review', '2026-07-26'),
  ('skill.shake', 1, 'Fun skills', 'Shake / give paw', 'A party trick that doubles as paw-handling practice.', '["Hold a treat in a loose fist at {name}''s chest height.","Most puppies paw at the fist - the instant a paw lifts, mark and treat.","Add an open palm as the target; treat for a paw landing in it.","Add the word shake just before offering the palm."]', array['skill.paw_handling'], 'exploration', 'tiny', '1-2/week', array['Grabbing the paw instead of shaping'], 'Grabbing the paw instead of letting {name} offer it.', 'Paw in palm on the word - cue applause from the household.', 'pending_professional_review', '2026-07-26');
