values
  ('rule.prep_window', 1, 'Preparation window', 'Selects prep.* items by their timing windows.', 'preparation', '{"selects":"prep.*","stage":["preparing"],"days_to_homecoming":"within_item_window"}', 0, '{"each_item":"once"}', 'short', 'anytime', 'P3', '{Puppy} comes home in {n} days.', 'pending_professional_review', '2026-07-26'),
  ('rule.active_skill_practice', 1, 'Active skill practice', 'Selects a session for an active TrainingGoal.', 'training', '{"goal_status":"active","not_paused":true}', 1, '{"per_skill":"skill_frequency_per_week"}', 'short', 'anytime', 'P3', '{Skill} is an active goal - last practiced {n} days ago.', 'pending_professional_review', '2026-07-26'),
  ('rule.start_next_skill', 1, 'Start next skill', 'Starts an eligible not-started skill.', 'training', '{"active_goal_count_lt":2,"prereqs":"met","stage":"matches"}', 3, null, 'tiny', 'anytime', 'P3', '{Puppy}''s {stage} stage is a good time to begin {skill}.', 'pending_professional_review', '2026-07-26'),
  ('rule.socialization_breadth', 1, 'Socialization breadth', 'Selects an experience from the least-recently-visited category.', 'socialization', '{"stages":["settling_in","foundations","exploration","teething","early_adolescence"],"category_not_excluded":true}', 2, '{"per_category_min_gap_days":2}', 'short', 'anytime', 'P3', '{Puppy} has not explored {category} recently - one calm, positive experience is plenty.', 'pending_professional_review', '2026-07-26'),
  ('rule.handling_cadence', 1, 'Handling cadence', 'Selects paw/body handling practice.', 'training', '{"stage_from":"settling_in","skill_not_paused":true}', 2, null, 'tiny', 'anytime', 'P3', 'Short, pleasant handling now makes grooming and vet visits easier later.', 'pending_professional_review', '2026-07-26'),
  ('rule.brushing', 1, 'Brushing', 'Selects a brushing session.', 'grooming', '{"stage_from":"settling_in","household_adjustable":true}', 3, null, 'tiny', 'anytime', 'P3', 'A brief brushing session keeps {Puppy} comfortable with grooming.', 'pending_professional_review', '2026-07-26'),
  ('rule.alone_time', 1, 'Alone-time practice', 'Selects alone-time practice.', 'training', '{"goal_active_or_stage_lte":"foundations"}', 2, null, 'short', 'anytime', 'P3', 'Short, easy departures now help {Puppy} feel fine alone later.', 'pending_professional_review', '2026-07-26'),
  ('rule.growth_photo', 1, 'Weekly growth photo', 'Selects an opt-in weekly growth photo.', 'life', '{"opt_in":true,"p2":true}', 7, null, 'tiny', 'anytime', 'P4', 'It has been a week - a quick photo keeps {Puppy}''s growth story going.', 'pending_professional_review', '2026-07-26'),
  ('rule.event_prep_vet', 1, 'Vet event preparation', 'Selects Gather records and questions before a vet appointment.', 'preparation', '{"event_kind":"vet_appointment","within_days":3}', 0, '{"each_event":"once"}', 'short', 'anytime', 'P2', '{Puppy}''s appointment is {when} - having records and questions ready helps.', 'pending_professional_review', '2026-07-26'),
  ('rule.homecoming_routine', 1, 'Homecoming routine', 'Selects routine confirmation when homecoming is today or tomorrow.', 'routine', '{"homecoming":"today_or_tomorrow"}', 0, '{"per_pet":"once"}', 'short', 'anytime', 'P3', '{Puppy} is almost home - a shared routine makes the first week calmer.', 'pending_professional_review', '2026-07-26');
